import{_ as e,o as d,c as o,ag as i}from"./chunks/framework.Fczl-Cb9.js";const u=JSON.parse('{"title":"Models & Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"models.md","filePath":"models.md","lastUpdated":1771746637000}'),a={name:"models.md"};function s(l,t,r,n,h,c){return d(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="models-pricing" tabindex="-1">Models &amp; Pricing <a class="header-anchor" href="#models-pricing" aria-label="Permalink to &quot;Models &amp; Pricing&quot;">​</a></h1><p>cloding supports 20+ model shortcuts across 5 CLI tools. Use built-in shortcuts or pass any OpenRouter model ID directly.</p><h2 id="openrouter-models-via-claude-code" tabindex="-1">OpenRouter Models (via Claude Code) <a class="header-anchor" href="#openrouter-models-via-claude-code" aria-label="Permalink to &quot;OpenRouter Models (via Claude Code)&quot;">​</a></h2><p>These models route through <a href="https://openrouter.ai" target="_blank" rel="noreferrer">OpenRouter</a> and use Claude Code as the underlying CLI tool.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Model</th><th style="text-align:right;">Input $/Mtok</th><th style="text-align:right;">Output $/Mtok</th><th>Best For</th></tr></thead><tbody><tr><td><code>qwen</code></td><td>Qwen 3 Coder</td><td style="text-align:right;">$0.12</td><td style="text-align:right;">$0.75</td><td>Day-to-day coding, high volume</td></tr><tr><td><code>deepseek</code></td><td>DeepSeek V3.2</td><td style="text-align:right;">$0.26</td><td style="text-align:right;">$0.38</td><td>Complex logic, algorithms</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Default Model</p><p>The default model is <strong>Qwen 3 Coder</strong> (<code>qwen</code>). Override with <code>-m</code> or the <code>CLODING_DEFAULT_MODEL</code> environment variable.</p></div><h2 id="anthropic-models-3-routing-modes-each" tabindex="-1">Anthropic Models (3 routing modes each) <a class="header-anchor" href="#anthropic-models-3-routing-modes-each" aria-label="Permalink to &quot;Anthropic Models (3 routing modes each)&quot;">​</a></h2><p>Each Anthropic model supports three routing modes — OpenRouter, direct Anthropic API, or your Claude Max subscription:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Model</th><th>Provider</th><th style="text-align:right;">Input $/Mtok</th><th style="text-align:right;">Output $/Mtok</th></tr></thead><tbody><tr><td><code>haiku</code> / <code>haiku-o</code></td><td>Claude Haiku 4.5</td><td>OpenRouter</td><td style="text-align:right;">$1.00</td><td style="text-align:right;">$5.00</td></tr><tr><td><code>haiku-a</code></td><td>Claude Haiku 4.5</td><td>Anthropic API</td><td style="text-align:right;">$1.00</td><td style="text-align:right;">$5.00</td></tr><tr><td><code>haiku-p</code></td><td>Claude Haiku 4.5</td><td>Paid plan</td><td style="text-align:right;">$0.00</td><td style="text-align:right;">$0.00</td></tr><tr><td><code>sonnet</code> / <code>sonnet-o</code></td><td>Claude Sonnet 4</td><td>OpenRouter</td><td style="text-align:right;">$3.00</td><td style="text-align:right;">$15.00</td></tr><tr><td><code>sonnet-a</code></td><td>Claude Sonnet 4</td><td>Anthropic API</td><td style="text-align:right;">$3.00</td><td style="text-align:right;">$15.00</td></tr><tr><td><code>sonnet-p</code></td><td>Claude Sonnet 4</td><td>Paid plan</td><td style="text-align:right;">$0.00</td><td style="text-align:right;">$0.00</td></tr><tr><td><code>opus</code> / <code>opus-o</code></td><td>Claude Opus 4.6</td><td>OpenRouter</td><td style="text-align:right;">$5.00</td><td style="text-align:right;">$25.00</td></tr><tr><td><code>opus-a</code></td><td>Claude Opus 4.6</td><td>Anthropic API</td><td style="text-align:right;">$5.00</td><td style="text-align:right;">$25.00</td></tr><tr><td><code>opus-p</code></td><td>Claude Opus 4.6</td><td>Paid plan</td><td style="text-align:right;">$0.00</td><td style="text-align:right;">$0.00</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Suffix guide</p><ul><li>No suffix or <code>-o</code> = OpenRouter (requires <code>OPENROUTER_API_KEY</code>)</li><li><code>-a</code> = Direct API (requires <code>ANTHROPIC_API_KEY</code>)</li><li><code>-p</code> = Paid plan (no key needed, uses your Claude Max subscription)</li></ul></div><h2 id="direct-tool-models" tabindex="-1">Direct Tool Models <a class="header-anchor" href="#direct-tool-models" aria-label="Permalink to &quot;Direct Tool Models&quot;">​</a></h2><p>These models use their native CLI tools directly, not Claude Code:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Model</th><th>Tool</th><th>Auth</th></tr></thead><tbody><tr><td><code>gemini</code></td><td>Gemini 2.5 Pro</td><td>Gemini CLI</td><td><code>OPENROUTER_API_KEY</code></td></tr><tr><td><code>gemini-3</code></td><td>Gemini 3 Pro (Paid Plan)</td><td>Gemini CLI</td><td>Gemini subscription</td></tr><tr><td><code>gemini-3-a</code></td><td>Gemini 3 Pro (API)</td><td>Gemini CLI</td><td><code>GOOGLE_API_KEY</code></td></tr><tr><td><code>codex-5</code></td><td>Codex (Paid Plan)</td><td>Codex CLI</td><td>ChatGPT Plus/Pro</td></tr><tr><td><code>codex-5-a</code></td><td>Codex 5.3 High (API)</td><td>Codex CLI</td><td><code>OPENAI_API_KEY</code></td></tr><tr><td><code>copilot</code></td><td>GitHub Copilot</td><td>Copilot CLI</td><td><code>GITHUB_TOKEN</code> or linked account</td></tr></tbody></table><h2 id="using-any-openrouter-model" tabindex="-1">Using Any OpenRouter Model <a class="header-anchor" href="#using-any-openrouter-model" aria-label="Permalink to &quot;Using Any OpenRouter Model&quot;">​</a></h2><p>Not limited to shortcuts — pass any OpenRouter model ID with <code>-m</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-llama/llama-4-scout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google/gemini-2.5-flash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic/claude-sonnet-4</span></span></code></pre></div><p>Browse the full catalog at <a href="https://openrouter.ai/models" target="_blank" rel="noreferrer">openrouter.ai/models</a>.</p><h2 id="list-all-models" tabindex="-1">List All Models <a class="header-anchor" href="#list-all-models" aria-label="Permalink to &quot;List All Models&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list-models</span></span></code></pre></div><p>This shows all configured shortcuts with their full model IDs and pricing.</p><h2 id="choosing-the-right-model" tabindex="-1">Choosing the Right Model <a class="header-anchor" href="#choosing-the-right-model" aria-label="Permalink to &quot;Choosing the Right Model&quot;">​</a></h2><p>Different models shine at different tasks:</p><p><strong>High-volume coding</strong> — Use <code>qwen</code> or <code>deepseek</code>. Dirt-cheap and surprisingly capable for most day-to-day work: writing functions, fixing bugs, adding tests, refactoring.</p><p><strong>Architecture and planning</strong> — Use <code>opus</code> or <code>sonnet</code>. When you need the model to understand a complex codebase and design a multi-file solution, the extra quality matters.</p><p><strong>Code review</strong> — Use <code>sonnet</code>, <code>opus</code>, or <code>codex-5</code>. Cost per review is low since reviews are mostly reading.</p><p><strong>CI/CD automation</strong> — Use <code>qwen</code>. Automated pipelines run many prompts; cost adds up fast. Qwen handles linting fixes, test generation, and boilerplate well.</p><p><strong>Large file context</strong> — Use <code>gemini</code> or <code>gemini-3</code>. Gemini has a massive context window, ideal for large files.</p><p><strong>Using your paid subscription</strong> — Use <code>-p</code> variants (<code>opus-p</code>, <code>sonnet-p</code>) for Claude Max, <code>codex-5</code> for ChatGPT, <code>gemini-3</code> for Gemini, <code>copilot</code> for GitHub Copilot.</p><div class="tip custom-block"><p class="custom-block-title">Mix models across tasks</p><p>You don&#39;t have to pick one model for everything. Use Opus to plan your architecture, then switch to Qwen to implement it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opus-p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;plan the auth module architecture&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;implement the auth module per the plan in PLAN.md&quot;</span></span></code></pre></div></div><h2 id="cost-comparison" tabindex="-1">Cost Comparison <a class="header-anchor" href="#cost-comparison" aria-label="Permalink to &quot;Cost Comparison&quot;">​</a></h2><p>A typical 30-minute coding session with Claude Code costs around <strong>$5</strong>. The same session with different models:</p><table tabindex="0"><thead><tr><th>Model</th><th>Estimated Cost</th><th>Savings</th></tr></thead><tbody><tr><td>Qwen 3 Coder</td><td>~$0.07</td><td>98.6%</td></tr><tr><td>DeepSeek V3.2</td><td>~$0.14</td><td>97.2%</td></tr><tr><td>Claude Haiku 4.5</td><td>~$1.00</td><td>80.0%</td></tr><tr><td>Claude Sonnet 4</td><td>~$3.00</td><td>40.0%</td></tr><tr><td>Claude Opus 4.6 (paid plan)</td><td>~$0.00</td><td>100%</td></tr><tr><td>Codex (paid plan)</td><td>~$0.00</td><td>100%</td></tr><tr><td>Gemini 3 Pro (paid plan)</td><td>~$0.00</td><td>100%</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Pricing note</p><p>Prices are pulled from OpenRouter and may change. Run <code>cloding --list-models</code> for current pricing. Paid plan models cost $0 per token — you pay through your monthly subscription.</p></div><h2 id="model-capabilities" tabindex="-1">Model Capabilities <a class="header-anchor" href="#model-capabilities" aria-label="Permalink to &quot;Model Capabilities&quot;">​</a></h2><p>Not all models support every feature equally:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Qwen</th><th>DeepSeek</th><th>Haiku</th><th>Sonnet</th><th>Opus</th><th>Gemini</th><th>Codex</th><th>Copilot</th></tr></thead><tbody><tr><td>File editing</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Terminal commands</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Multi-file changes</td><td>Partial</td><td>Yes</td><td>Partial</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Complex planning</td><td>Partial</td><td>Partial</td><td>No</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Partial</td></tr><tr><td>Long context</td><td>Partial</td><td>Yes</td><td>Partial</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Partial</td></tr></tbody></table><p>&quot;Partial&quot; = works but may need more guidance.</p><h2 id="custom-shortcuts" tabindex="-1">Custom Shortcuts <a class="header-anchor" href="#custom-shortcuts" aria-label="Permalink to &quot;Custom Shortcuts&quot;">​</a></h2><p>You can add your own model shortcuts by editing the <code>models.json</code> file. See <a href="/cloding/custom-models">Custom Models</a> for details.</p>`,39)])])}const g=e(a,[["render",s]]);export{u as __pageData,g as default};
